func (u *AIUsageAllocationUpsertBulk) DoNothing() *AIUsageAllocationUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the AIUsageAllocationCreateBulk.OnConflict
// documentation for more info.
func (u *AIUsageAllocationUpsertBulk) Update(set func(*AIUsageAllocationUpsert)) *AIUsageAllocationUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&AIUsageAllocationUpsert{UpdateSet: update})
	}))
	return u
}

// Exec executes the query.
func (u *AIUsageAllocationUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("db: OnConflict was set for builder %d. Set it on the AIUsageAllocationCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("db: missing options for AIUsageAllocationCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *AIUsageAllocationUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
